function uid(){ return crypto.randomUUID() }
function esc(value=''){ return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c])) }
function attr(value=''){ return esc(value).replace(/`/g,'&#096;') }
function fmtCurrency(value){ if(value===null||value===undefined||Number.isNaN(Number(value))) return '—'; return `NPR ${new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}).format(Number(value))}` }
function fmtDate(value, withTime=false){ if(!value)return '—'; const d=new Date(value); if(Number.isNaN(d.getTime()))return esc(value); return new Intl.DateTimeFormat('en-GB',withTime?{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'short',year:'numeric'}).format(d) }
function daysSince(value){ if(!value)return 99; return Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/86400000)) }
function stageLabel(value){ return STAGES.find(s=>s[0]===value)?.[1] || value }
function normalizeText(v){ return String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'') }
function normalizePhone(v){ return String(v||'').replace(/\D/g,'').replace(/^977/,'') }
function normalizeDomain(v){ if(!v)return ''; try{return new URL(/^https?:/.test(v)?v:`https://${v}`).hostname.replace(/^www\./,'').toLowerCase()}catch{return normalizeText(v)} }
function todayIso(){ return new Date().toISOString() }
function inputDateTime(value){ if(!value)return ''; const d=new Date(value); return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16) }
function toast(message,type='success'){ toastRoot.innerHTML=`<div class="toast ${type==='error'?'error':''}">${esc(message)}</div>`; setTimeout(()=>toastRoot.innerHTML='',2800) }
function badgeStage(stage){ return `<span class="badge stage-${attr(stage)}">${esc(stageLabel(stage))}</span>` }
function badgePriority(priority){ return `<span class="badge priority-${attr(priority||'medium')}">${esc(priority||'medium')}</span>` }
function badgeStatus(status){ return `<span class="badge status-${attr(status)}">${esc(String(status||'').replaceAll('_',' '))}</span>` }
function scoreClass(score){ return Number(score)>=80?'hot':Number(score)>=50?'warm':'cold' }
function badgeScore(score=0){ const c=scoreClass(score); return `<span class="score-badge ${c}">${Number(score)||0} · ${c}</span>` }

function calculateScore(lead){
  const budget=Number(lead.estimated_budget||lead.expected_monthly_value||0)
  const budgetScore=budget>=50000?20:budget>=30000?16:budget>=20000?12:budget>=10000?8:budget>0?4:0
  const engagement=Math.min(15,Math.max(0,Number(lead.engagement_level||2)*3))
  const decision=lead.decision_maker_contacted?10:0
  const meeting=Math.min(10,Math.max(0,Number(lead.meeting_interest||0)*2))
  const urgency=Math.min(10,Math.max(0,Number(lead.urgency_level||0)*2))
  const completeness=Math.min(15,Math.max(0,Math.round(Number(lead.requirements_completeness||0)*.15)))
  const stageMap={new:0,contacted:2,requirements:5,proposal_preparing:7,proposal_sent:10,follow_up:9,meeting:12,negotiating:15,won:20,lost:0,on_hold:3}
  const stage=stageMap[lead.stage||'new']||0
  const inactive=daysSince(lead.last_activity_at||lead.updated_at||lead.created_at)
  const freshness=inactive<=1?10:inactive<=3?8:inactive<=7?5:inactive<=10?2:0
  const calculated=Math.min(100,Math.max(0,budgetScore+engagement+decision+meeting+urgency+completeness+stage+freshness))
  const total=lead.score_override!==null&&lead.score_override!==undefined?Number(lead.score_override):calculated
  return {total,factors:[
    ['Budget / value',budgetScore,20,budget?`Budget NPR ${budget.toLocaleString('en-IN')}`:'No budget recorded'],
    ['Engagement',engagement,15,'Reply speed and quality'],['Decision-maker',decision,10,lead.decision_maker_contacted?'Confirmed':'Not confirmed'],
    ['Meeting interest',meeting,10,'Interest in a meeting'],['Urgency',urgency,10,'How soon services are needed'],
    ['Requirements',completeness,15,`${Number(lead.requirements_completeness||0)}% complete`],['Stage progress',stage,20,stageLabel(lead.stage||'new')],
    ['Recent activity',freshness,10,`${inactive} day(s) since activity`],
  ]}
}

function staleResult(lead){
  if(['won','lost'].includes(lead.stage))return {stale:false}
  const days=daysSince(lead.last_activity_at||lead.updated_at||lead.created_at)
  const remarks=String(lead.remarks||'').toLowerCase()
  if(lead.stage==='proposal_sent'&&days>=5)return {stale:true,days,reason:'Proposal sent with no activity for 5+ days',suggestion:'Send a short proposal follow-up and ask for a review timeline.'}
  if((remarks.includes('waiting')||remarks.includes('review'))&&days>=7)return {stale:true,days,reason:'Client is reviewing/waiting with no activity for 7+ days',suggestion:'Ask whether any questions or revisions are needed.'}
  if(lead.stage==='meeting'&&days>=2&&!lead.proposal_url)return {stale:true,days,reason:'Meeting stage has no proposal after 2+ days',suggestion:'Prepare and send the proposal.'}
  if(lead.stage==='requirements'&&days>=2)return {stale:true,days,reason:'Requirements collected but proposal work has not progressed',suggestion:'Start proposal preparation and assign an owner.'}
  if(days>=10)return {stale:true,days,reason:'Active lead has no activity for 10+ days',suggestion:'Contact the client or move the lead to On Hold/Lost.'}
  return {stale:false}
}

function findDuplicates(candidate, list=state.leads){
  return list.map(lead=>{ const reasons=[]; let confidence=0
    if(candidate.company_name&&normalizeText(candidate.company_name)===normalizeText(lead.company_name)){reasons.push('Same company name');confidence+=40}
    const cp=[candidate.phone,candidate.whatsapp].map(normalizePhone).filter(Boolean), ep=[lead.phone,lead.whatsapp].map(normalizePhone).filter(Boolean)
    if(cp.some(p=>ep.includes(p))){reasons.push('Same phone / WhatsApp');confidence+=45}
    if(candidate.email&&normalizeText(candidate.email)===normalizeText(lead.email)){reasons.push('Same email');confidence+=50}
    if(candidate.website&&normalizeDomain(candidate.website)===normalizeDomain(lead.website)){reasons.push('Same website');confidence+=35}
    const cs=[candidate.instagram,candidate.facebook,candidate.tiktok].map(normalizeText).filter(Boolean), es=[lead.instagram,lead.facebook,lead.tiktok].map(normalizeText).filter(Boolean)
    if(cs.some(v=>es.includes(v))){reasons.push('Same social handle');confidence+=35}
    return {lead,reasons,confidence:Math.min(100,confidence)}
  }).filter(m=>m.reasons.length).sort((a,b)=>b.confidence-a.confidence)
}

function smartParse(text){
  const lower=String(text||'').toLowerCase(), num=(re)=>{const m=lower.match(re);return m?Number(m[1].replace(/,/g,'')):undefined}
  const budget=num(/(?:budget|rs\.?|npr|रु)\s*(?:is|around|approx(?:imately)?|of)?\s*([0-9,]+)/i)||num(/([0-9,]+)\s*(?:budget|rs|npr)/i)
  const videos=num(/([0-9]+)\s*(?:-|to)?\s*(?:[0-9]+\s*)?(?:videos?|reels?)\s*(?:monthly|per month|a month)/i)||num(/(?:monthly|per month)\s*([0-9]+)\s*(?:videos?|reels?)/i)
  const graphics=num(/([0-9]+)\s*(?:graphics?|posts?|banners?)\s*(?:monthly|per month|a month)/i)
  let action='',stage=''
  if(/send.*proposal|proposal.*send/.test(lower)){action='Prepare and send proposal';stage='proposal_preparing'}
  if(/proposal sent|sent.*proposal/.test(lower)){action='Follow up on proposal';stage='proposal_sent'}
  if(/schedule.*meeting|setup.*meeting|set up.*meeting/.test(lower)){action='Schedule a meeting';stage='meeting'}
  if(/no reply|waiting for reply|follow up|follow-up/.test(lower)){action=action||'Follow up with client';stage=stage||'follow_up'}
  if(/not interested|no deal|rejected/.test(lower))stage='lost'
  if(/confirmed|signed|deal done|client onboarded/.test(lower))stage='won'
  const cleaned=String(text||'').trim().replace(/\s+/g,' ').replace(/(^|[.!?]\s+)([a-z])/g,(_,p,l)=>p+l.toUpperCase())
  return {budget,videos,graphics,action,stage,cleaned}
}

