async function loadConfig(){
  try{ const r=await fetch('/api/public-config',{cache:'no-store'}); state.config=await r.json() }catch{ state.config={supabaseUrl:'',supabasePublishableKey:''} }
  state.cloud=Boolean(state.config.supabaseUrl&&state.config.supabasePublishableKey)
}

async function authRequest(path,options={}){
  const {supabaseUrl,supabasePublishableKey}=state.config
  return fetch(`${supabaseUrl}/auth/v1/${path}`,{...options,headers:{apikey:supabasePublishableKey,'Content-Type':'application/json',...(options.headers||{})}})
}
async function restRequest(table,query='',options={}){
  if(!state.session?.access_token)throw new Error('Please sign in again.')
  const {supabaseUrl,supabasePublishableKey}=state.config
  const response=await fetch(`${supabaseUrl}/rest/v1/${table}${query}`,{...options,headers:{apikey:supabasePublishableKey,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':'application/json',Prefer:'return=representation',...(options.headers||{})}})
  if(response.status===401&&state.session.refresh_token){ await refreshSession(); return restRequest(table,query,options) }
  if(!response.ok){ let msg=`Database error (${response.status})`;try{const e=await response.json();msg=e.message||e.hint||msg}catch{}throw new Error(msg) }
  if(response.status===204)return []
  const text=await response.text();return text?JSON.parse(text):[]
}
async function refreshSession(){
  const response=await authRequest('token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:state.session.refresh_token})})
  if(!response.ok){ logout(false);throw new Error('Session expired. Please sign in again.') }
  state.session=await response.json();localStorage.setItem(SESSION_KEY,JSON.stringify(state.session))
}
async function login(email,password){
  const response=await authRequest('token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})})
  if(!response.ok){const e=await response.json().catch(()=>({}));throw new Error(e.error_description||e.msg||'Invalid email or password.')}
  state.session=await response.json();localStorage.setItem(SESSION_KEY,JSON.stringify(state.session));await loadAll();location.hash='#/dashboard'
}
async function logout(render=true){
  if(state.cloud&&state.session?.access_token)await authRequest('logout',{method:'POST',headers:{Authorization:`Bearer ${state.session.access_token}`}}).catch(()=>{})
  state.session=null;state.profile=null;localStorage.removeItem(SESSION_KEY);if(render){location.hash='#/login';renderApp()}
}
function localSave(){localStorage.setItem(LOCAL_KEY,JSON.stringify({leads:state.leads,requirements:state.requirements,activities:state.activities,tasks:state.tasks,clients:state.clients,deliverables:state.deliverables,payments:state.payments,quickReplies:state.quickReplies}))}
function localLoad(){try{const d=JSON.parse(localStorage.getItem(LOCAL_KEY));if(d?.leads)return d}catch{}localStorage.setItem(LOCAL_KEY,JSON.stringify(demo));return structuredClone(demo)}

async function loadAll(){
  state.loading=true
  if(!state.cloud){ Object.assign(state,localLoad());state.profile={full_name:'Vireon Admin',role:'admin'};state.loading=false;return }
  if(!state.session){try{state.session=JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{} }
  if(!state.session){state.loading=false;return}
  try{
    const [leads,requirements,activities,tasks,clients,deliverables,payments,quickReplies,profiles]=await Promise.all([
      restRequest('leads','?select=*&order=updated_at.desc'),restRequest('lead_requirements','?select=*'),restRequest('activities','?select=*&order=created_at.desc'),restRequest('tasks','?select=*&order=due_at.asc.nullslast'),restRequest('clients','?select=*&order=updated_at.desc'),restRequest('deliverables','?select=*&order=due_date.asc.nullslast'),restRequest('payments','?select=*&order=due_date.asc.nullslast'),restRequest('quick_replies','?select=*&order=is_favorite.desc,created_at.desc'),restRequest('profiles',`?select=*&id=eq.${state.session.user.id}`),
    ])
    Object.assign(state,{leads,requirements,activities,tasks,clients,deliverables,payments,quickReplies});state.profile=profiles[0]||{full_name:state.session.user.email?.split('@')[0]||'Team Member',role:'member'}
  }catch(error){toast(error.message,'error')}
  state.loading=false
}

const DB_TABLE={requirements:'lead_requirements',quickReplies:'quick_replies'}
function dbTable(table){return DB_TABLE[table]||table}
async function insertRecord(table,record){
  if(!state.cloud){const item={id:record.id||uid(),created_at:record.created_at||todayIso(),...record};state[table].unshift(item);localSave();return item}
  const rows=await restRequest(dbTable(table),'',{method:'POST',body:JSON.stringify(record)});return rows[0]
}
async function updateRecord(table,id,changes){
  if(!state.cloud){const idx=state[table].findIndex(x=>x.id===id);if(idx>=0)state[table][idx]={...state[table][idx],...changes};localSave();return state[table][idx]}
  const rows=await restRequest(dbTable(table),`?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(changes)});return rows[0]
}
async function deleteRecord(table,id){
  if(!state.cloud){state[table]=state[table].filter(x=>x.id!==id);localSave();return}
  await restRequest(dbTable(table),`?id=eq.${encodeURIComponent(id)}`,{method:'DELETE'})
}
async function saveLead(data,reqData,existingId){
  const now=todayIso();const base={...data,estimated_budget:numOrNull(data.estimated_budget),expected_monthly_value:numOrNull(data.expected_monthly_value),closing_probability:numOrNull(data.closing_probability),meeting_interest:Number(data.meeting_interest||0),urgency_level:Number(data.urgency_level||0),engagement_level:Number(data.engagement_level||0),requirements_completeness:Number(data.requirements_completeness||0),decision_maker_contacted:Boolean(data.decision_maker_contacted),updated_at:now,last_activity_at:data.last_activity_at||now}
  base.score=calculateScore(base).total;base.stale_reason=staleResult({...base,created_at:data.created_at||now}).reason||null
  let lead
  if(existingId){lead=await updateRecord('leads',existingId,base);state.leads=state.leads.map(x=>x.id===existingId?lead:x)}else{lead=await insertRecord('leads',{...base,created_at:now});state.leads=[lead,...state.leads.filter(x=>x.id!==lead.id)]}
  if(reqData){const existing=state.requirements.find(r=>r.lead_id===lead.id);const req={...reqData,lead_id:lead.id,monthly_videos:Number(reqData.monthly_videos||0),monthly_graphics:Number(reqData.monthly_graphics||0),approximate_budget:numOrNull(reqData.approximate_budget)};let saved;if(existing)saved=await updateRecord('requirements',existing.id,req);else saved=await insertRecord('requirements',req);state.requirements=existing?state.requirements.map(r=>r.id===existing.id?saved:r):[saved,...state.requirements]}
  localSave();return lead
}
async function addActivity(data){const activity=await insertRecord('activities',{...data,created_at:todayIso()});state.activities=[activity,...state.activities.filter(a=>a.id!==activity.id)];if(activity.lead_id){const lead=state.leads.find(l=>l.id===activity.lead_id);if(lead){const updated=await updateRecord('leads',lead.id,{last_activity_at:activity.created_at,next_follow_up_at:activity.next_follow_up_at||lead.next_follow_up_at,updated_at:todayIso()});state.leads=state.leads.map(l=>l.id===lead.id?updated:l)}}localSave();return activity}
async function createTask(data){const task=await insertRecord('tasks',{status:'pending',priority:'medium',...data,created_at:todayIso()});state.tasks=[...state.tasks.filter(t=>t.id!==task.id),task];localSave();return task}
async function saveClient(data,lead){
  const now=todayIso();const payload={...data,monthly_fee:Number(data.monthly_fee||0),services:Array.isArray(data.services)?data.services:String(data.services||'').split(',').map(s=>s.trim()).filter(Boolean),updated_at:now}
  let client
  if(data.id){const id=data.id;delete payload.id;client=await updateRecord('clients',id,payload);state.clients=state.clients.map(c=>c.id===id?client:c)}else{client=await insertRecord('clients',{...payload,lead_id:lead?.id||data.lead_id||null,created_at:now});state.clients=[client,...state.clients.filter(c=>c.id!==client.id)]}
  if(lead){const updated=await updateRecord('leads',lead.id,{stage:'won',closing_probability:100,updated_at:now});state.leads=state.leads.map(l=>l.id===lead.id?updated:l);await addActivity({lead_id:lead.id,client_id:client.id,type:'stage_change',summary:'Lead converted to signed client',details:`Client workspace created at ${fmtCurrency(client.monthly_fee)} per ${client.billing_cycle}.`})}
  localSave();return client
}
function numOrNull(value){return value===''||value===null||value===undefined?null:Number(value)}

function route(){const raw=(location.hash||'#/dashboard').replace(/^#\/?/,'');const [pathPart,queryString='']=raw.split('?');const parts=pathPart.split('/').filter(Boolean);return {page:parts[0]||'dashboard',id:parts[1]||null,query:new URLSearchParams(queryString)}}
function pageTitle(page){return NAV.find(n=>n[0]===page)?.[1]||'Vireon CRM'}
function renderApp(){
  if(state.loading){app.innerHTML='<div class="app-loading"><div class="loader-mark">VIREON</div><p>Loading secure workspace…</p></div>';return}
  const r=route()
  if(state.cloud&&!state.session&&r.page!=='login'){location.hash='#/login';return}
  if(r.page==='login'){renderLogin();return}
  app.innerHTML=layoutHtml(pageTitle(r.page),renderPage(r))
  bindPipelineDnD()
}
function layoutHtml(title,content){
  const active=route().page, initials=String(state.profile?.full_name||'VA').slice(0,2).toUpperCase()
  return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand-row"><div class="wordmark"><strong>VIREON</strong><span>IDEAS MADE VISIBLE</span></div><button class="mobile-close icon-btn" data-action="mobile-close">×</button></div><div class="product-name"><span class="product-dot"></span><div><strong>CRM</strong><small>Leads & client delivery</small></div></div><nav class="side-nav">${NAV.map(([id,label,icon])=>`<a href="#/${id}" class="${active===id?'active':''}"><span>${icon}</span><span>${label}</span></a>`).join('')}</nav><div class="sidebar-footer"><div class="user-chip"><div class="avatar">${esc(initials)}</div><div><strong>${esc(state.profile?.full_name||'Vireon Team')}</strong><small>${esc(state.profile?.role||'member')} · ${state.cloud?'Cloud':'Local preview'}</small></div></div><button class="sidebar-action" data-action="logout"><span>↪</span><span>Sign out</span></button></div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu icon-btn" data-action="mobile-open">☰</button><div><p class="eyebrow">VIREON INTERNAL SYSTEM</p><h1>${esc(title)}</h1></div><div class="topbar-right"><span class="mode-pill ${state.cloud?'cloud':'local'}">${state.cloud?'Cloud database':'Local preview mode'}</span></div></header>${!state.cloud?'<div class="demo-banner"><strong>Local preview:</strong> data is saved only in this browser. Connect Supabase before your team starts using it.</div>':''}<div class="page-wrap">${content}</div></main><div class="mobile-scrim" data-action="mobile-close"></div></div>`
}
function renderPage(r){switch(r.page){case'dashboard':return dashboardHtml();case'leads':return r.id?leadDetailHtml(r.id):leadsHtml();case'pipeline':return pipelineHtml();case'follow-ups':return followUpsHtml();case'clients':return r.id?clientDetailHtml(r.id):clientsHtml();case'activities':return activitiesHtml();case'quick-replies':return quickRepliesHtml();case'reports':return reportsHtml();case'settings':return settingsHtml();default:return dashboardHtml()}}
function renderLogin(){
  if(!state.cloud){app.innerHTML=`<main class="login-page"><section class="login-brand"><div class="wordmark large"><strong>VIREON</strong><span>IDEAS MADE VISIBLE</span></div><h1>Every client conversation.<br>Every commitment.<br><em>One clear system.</em></h1><p>Internal lead management, client delivery and payment visibility for the Vireon team.</p></section><section class="login-panel"><div class="login-card"><div class="login-icon">🔒</div><p class="eyebrow">LOCAL PREVIEW</p><h2>Supabase is not connected</h2><div class="local-login-note">You can open the local demo now. For shared team access, add the Supabase variables in Netlify.</div><div class="login-actions"><button class="primary-btn full" data-action="local-enter">Open local preview</button></div></div></section></main>`;return}
  app.innerHTML=`<main class="login-page"><section class="login-brand"><div class="wordmark large"><strong>VIREON</strong><span>IDEAS MADE VISIBLE</span></div><h1>Every client conversation.<br>Every commitment.<br><em>One clear system.</em></h1><p>Internal lead management, client delivery and payment visibility for the Vireon team.</p></section><section class="login-panel"><div class="login-card"><div class="login-icon">🔒</div><p class="eyebrow">TEAM ACCESS</p><h2>Sign in to Vireon CRM</h2><p>Use the email and password created by the administrator.</p><form id="login-form" class="form-stack"><label><span>Email</span><input name="email" type="email" required></label><label><span>Password</span><input name="password" type="password" required></label><div id="login-error" class="auth-error"></div><button class="primary-btn full">Sign in</button></form></div></section></main>`
}

function stat(label,value,note,tone='default'){return `<article class="stat-card tone-${tone}"><span>${esc(label)}</span><strong>${value}</strong><small>${esc(note||'')}</small></article>`}
function dashboardHtml(){
  const active=state.leads.filter(l=>!['won','lost'].includes(l.stage)),today=new Date().toDateString();const todayTasks=state.tasks.filter(t=>t.status==='pending'&&t.due_at&&new Date(t.due_at).toDateString()===today);const overdue=state.tasks.filter(t=>t.status==='pending'&&t.due_at&&new Date(t.due_at)<new Date());const stale=active.map(lead=>({lead,result:staleResult(lead)})).filter(x=>x.result.stale);const won=state.leads.filter(l=>l.stage==='won').length,lost=state.leads.filter(l=>l.stage==='lost').length;const pipeline=active.reduce((s,l)=>s+Number(l.expected_monthly_value||l.estimated_budget||0)*(Number(l.closing_probability||50)/100),0);const revenue=state.clients.filter(c=>c.status==='active').reduce((s,c)=>s+Number(c.monthly_fee||0),0);const total=state.deliverables.reduce((s,d)=>s+Number(d.quantity||0),0),done=state.deliverables.reduce((s,d)=>s+Number(d.completed_quantity||0),0);const conversion=won+lost?Math.round(won/(won+lost)*100):0
  return `<div class="page-actions"><div><h2>Good overview, better follow-through.</h2><p>What needs attention across leads and signed clients.</p></div><button class="primary-btn" data-action="lead-add">＋ Add lead</button></div><section class="stats-grid">${stat('Total leads',state.leads.length,`${active.length} active`)}${stat('Follow-ups today',todayTasks.length,'Tasks requiring action','blue')}${stat('Overdue',overdue.length,'Do these first',overdue.length?'danger':'default')}${stat('Pipeline value',fmtCurrency(pipeline),'Probability weighted')}${stat('Confirmed monthly revenue',fmtCurrency(revenue),`${state.clients.filter(c=>c.status==='active').length} active clients`,'success')}${stat('Lead conversion',`${conversion}%`,`${won} won / ${lost} lost`)}${stat('Needs attention',stale.length,'Stale active leads',stale.length?'danger':'default')}${stat('Client work progress',total?`${Math.round(done/total*100)}%`:'—',`${done} of ${total} deliverables done`)}</section><section class="dashboard-grid"><article class="panel span-2"><div class="panel-header"><div><p class="eyebrow">PIPELINE</p><h3>Leads by stage</h3></div><a class="text-link" href="#/pipeline">Open pipeline →</a></div><div class="stage-bars">${STAGES.filter(s=>!['won','lost'].includes(s[0])).map(([id,label])=>{const count=state.leads.filter(l=>l.stage===id).length,pct=state.leads.length?Math.max(3,count/state.leads.length*100):0;return`<div class="stage-bar-row"><span>${esc(label)}</span><div><i style="width:${pct}%"></i></div><strong>${count}</strong></div>`}).join('')}</div></article><article class="panel"><div class="panel-header"><div><p class="eyebrow">CLIENT DELIVERY</p><h3>Active client health</h3></div></div><div class="client-health-list">${state.clients.filter(c=>c.status==='active').slice(0,5).map(c=>{const items=state.deliverables.filter(d=>d.client_id===c.id),q=items.reduce((s,d)=>s+Number(d.quantity),0),x=items.reduce((s,d)=>s+Number(d.completed_quantity),0),p=q?Math.round(x/q*100):0;return`<a class="client-health" href="#/clients/${c.id}"><div><strong>${esc(c.company_name)}</strong><small>${esc(c.package_name||'Custom package')} · ${fmtCurrency(c.monthly_fee)}</small></div><div class="progress-ring"><span>${p}%</span></div></a>`}).join('')||'<p class="muted">No signed clients yet.</p>'}</div></article><article class="panel span-2"><div class="panel-header"><div><p class="eyebrow">AUTOMATIC STALE DETECTION</p><h3>Needs attention</h3></div><span class="count-pill">${stale.length}</span></div><div class="attention-list">${stale.slice(0,6).map(({lead,result})=>`<a href="#/leads/${lead.id}" class="attention-item"><div class="attention-icon">!</div><div class="grow"><div class="inline-row"><strong>${esc(lead.company_name)}</strong>${badgeStage(lead.stage)}${badgePriority(lead.priority)}</div><p>${esc(result.reason)}</p><small>Suggested: ${esc(result.suggestion)}</small></div>${badgeScore(lead.score||calculateScore(lead).total)}</a>`).join('')||'<div class="positive-empty"><div><strong>No stale leads</strong><p>Your active pipeline has recent activity.</p></div></div>'}</div></article><article class="panel"><div class="panel-header"><div><p class="eyebrow">UP NEXT</p><h3>Follow-ups</h3></div><a class="text-link" href="#/follow-ups">View all</a></div><div class="compact-list">${state.tasks.filter(t=>t.status==='pending').slice(0,6).map(t=>`<div class="compact-item"><span>◷</span><div><strong>${esc(t.title)}</strong><small>${fmtDate(t.due_at,true)}</small></div></div>`).join('')||'<p class="muted">No open tasks.</p>'}</div></article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">HISTORY</p><h3>Recent activity</h3></div><a class="text-link" href="#/activities">All activity</a></div><div class="activity-strip">${state.activities.slice(0,6).map(a=>{const entity=state.leads.find(l=>l.id===a.lead_id)?.company_name||state.clients.find(c=>c.id===a.client_id)?.company_name||'Internal';return`<div class="activity-card"><span class="activity-type">${esc(a.type.replaceAll('_',' '))}</span><strong>${esc(a.summary)}</strong><p>${esc(entity)}</p><small>${fmtDate(a.created_at,true)}</small></div>`}).join('')}</div></article></section>`
}

function leadsHtml(){
  const f=state.filters.leads||{q:'',stage:'',industry:'',source:'',stale:false};const rows=state.leads.filter(l=>{const hay=[l.company_name,l.contact_person,l.phone,l.email,l.remarks].join(' ').toLowerCase();return(!f.q||hay.includes(f.q.toLowerCase()))&&(!f.stage||l.stage===f.stage)&&(!f.industry||l.industry===f.industry)&&(!f.source||l.lead_source===f.source)&&(!f.stale||staleResult(l).stale)})
  return `<div class="page-actions"><div><h2>All leads</h2><p>Search, filter and open the complete history for every opportunity.</p></div><button class="primary-btn" data-action="lead-add">＋ Add lead</button></div><section class="filter-bar"><label class="search-box">⌕<input data-filter="lead-q" placeholder="Search company, phone, email or notes" value="${attr(f.q)}"></label><select data-filter="lead-stage"><option value="">All stages</option>${STAGES.map(([v,l])=>`<option value="${v}" ${f.stage===v?'selected':''}>${l}</option>`).join('')}</select><select data-filter="lead-industry"><option value="">All industries</option>${INDUSTRIES.map(v=>`<option ${f.industry===v?'selected':''}>${v}</option>`).join('')}</select><select data-filter="lead-source"><option value="">All sources</option>${SOURCES.map(v=>`<option ${f.source===v?'selected':''}>${v}</option>`).join('')}</select><button class="filter-toggle ${f.stale?'active':''}" data-action="toggle-stale">⚑ Stale only</button></section><section class="panel table-panel"><div class="panel-header"><div><p class="eyebrow">LEAD DATABASE</p><h3>${rows.length} records</h3></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Company</th><th>Contact</th><th>Stage</th><th>Priority</th><th>Score</th><th>Value</th><th>Next follow-up</th><th>Last note</th></tr></thead><tbody>${rows.map(l=>`<tr><td><a class="table-primary" href="#/leads/${l.id}">${esc(l.company_name)}</a><small>${esc(l.industry||'Unclassified')} · ${esc(l.lead_source||'No source')}</small></td><td><span>${esc(l.contact_person||'—')}</span><small>${esc(l.phone||l.email||'No contact')}</small></td><td>${badgeStage(l.stage)}${staleResult(l).stale?'<small class="stale-text">Needs attention</small>':''}</td><td>${badgePriority(l.priority)}</td><td>${badgeScore(l.score||calculateScore(l).total)}</td><td><strong>${fmtCurrency(l.expected_monthly_value||l.estimated_budget)}</strong><small>${Number(l.closing_probability||0)}% probability</small></td><td>${fmtDate(l.next_follow_up_at,true)}</td><td class="remarks-cell">${esc(l.remarks||'—')}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-state"><h3>No leads found</h3><p>Try removing a filter or add a new lead.</p></div>'}</section>`
}
function leadDetailHtml(id){
  const lead=state.leads.find(l=>l.id===id);if(!lead)return '<div class="empty-state"><h3>Lead not found</h3><a href="#/leads">Back to leads</a></div>'
  const req=state.requirements.find(r=>r.lead_id===id)||{},score=calculateScore(lead),stale=staleResult(lead),acts=state.activities.filter(a=>a.lead_id===id),tasks=state.tasks.filter(t=>t.lead_id===id&&t.status==='pending')
  return `<div class="detail-back"><a href="#/leads">← All leads</a></div><section class="profile-hero"><div><div class="inline-row"><p class="eyebrow">LEAD PROFILE</p>${badgeStage(lead.stage)}${badgePriority(lead.priority)}</div><h2>${esc(lead.company_name)}</h2><p>${esc(lead.remarks||'No current situation recorded.')}</p><div class="hero-links">${lead.proposal_url?`<a href="${attr(lead.proposal_url)}" target="_blank">↗ Proposal</a>`:''}${lead.drive_folder_url?`<a href="${attr(lead.drive_folder_url)}" target="_blank">↗ Drive folder</a>`:''}</div></div><div class="hero-actions"><button class="secondary-btn" data-action="lead-edit" data-id="${id}">Edit</button><button class="secondary-btn" data-action="activity-add" data-lead="${id}">Add activity</button>${lead.stage!=='won'?`<button class="primary-btn" data-action="client-convert" data-lead="${id}">Sign client</button>`:''}</div></section>${stale.stale?`<section class="stale-callout"><div><strong>${esc(stale.reason)}</strong><p>${esc(stale.suggestion)}</p></div><span>${stale.days} days</span></section>`:''}<section class="lead-detail-grid"><article class="panel"><div class="panel-header"><div><p class="eyebrow">CONTACT</p><h3>Lead information</h3></div></div>${detailList([['Contact person',lead.contact_person],['Phone',lead.phone],['WhatsApp',lead.whatsapp],['Email',lead.email],['Industry',lead.industry],['Lead source',lead.lead_source],['First contacted',fmtDate(lead.date_first_contacted)],['Next follow-up',fmtDate(lead.next_follow_up_at,true)]])}</article><article class="panel"><div class="panel-header"><div><p class="eyebrow">VALUE</p><h3>Commercial picture</h3></div>${badgeScore(score.total)}</div>${detailList([['Estimated budget',fmtCurrency(lead.estimated_budget)],['Expected monthly value',fmtCurrency(lead.expected_monthly_value)],['Closing probability',`${Number(lead.closing_probability||0)}%`],['Decision-maker contacted',lead.decision_maker_contacted?'Yes':'No']])}<div class="score-breakdown">${score.factors.map(([label,value,max,ex])=>`<div class="score-factor"><div><span>${esc(label)}</span><strong>${value}/${max}</strong></div><div class="mini-progress"><i style="width:${value/max*100}%"></i></div><small>${esc(ex)}</small></div>`).join('')}</div></article><article class="panel"><div class="panel-header"><div><p class="eyebrow">REQUIREMENTS</p><h3>What they need</h3></div></div>${detailList([['Videos monthly',req.monthly_videos],['Graphics monthly',req.monthly_graphics],['Shoot frequency',req.shoot_frequency],['Approx. budget',fmtCurrency(req.approximate_budget)],['Models',req.models_required?'Required':'No / unknown'],['Voice-over',req.voiceover_required?'Required':'No / unknown'],['Social handling',req.social_media_handling_required?'Required':'No / unknown']])}<p class="long-text">${esc(req.special_expectations||'No special expectations recorded.')}</p></article><article class="panel"><div class="panel-header"><div><p class="eyebrow">NEXT ACTIONS</p><h3>Open tasks</h3></div></div><div class="compact-list">${tasks.map(t=>`<div class="compact-item"><span>◷</span><div><strong>${esc(t.title)}</strong><small>${fmtDate(t.due_at,true)}</small></div></div>`).join('')||'<p class="muted">No open follow-up tasks.</p>'}</div></article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">COMPLETE HISTORY</p><h3>Activity timeline</h3></div><button class="secondary-btn compact" data-action="activity-add" data-lead="${id}">Add activity</button></div>${timelineHtml(acts)}</article></section>`
}
function detailList(rows){return `<dl class="detail-list">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v===0?'0':(v||'—')}</dd></div>`).join('')}</dl>`}
function timelineHtml(items){return `<div class="timeline">${items.map(a=>`<div class="timeline-item"><div class="timeline-dot"></div><div><div class="inline-row"><strong>${esc(a.summary)}</strong><span class="activity-type">${esc(String(a.type).replaceAll('_',' '))}</span></div><p>${esc(a.details||a.client_response||'No extra details')}</p>${a.next_action?`<small>Next: ${esc(a.next_action)}</small>`:''}<small>${fmtDate(a.created_at,true)}</small></div></div>`).join('')||'<p class="muted">No activity recorded yet.</p>'}</div>`}
function pipelineHtml(){return `<div class="page-actions"><div><h2>Lead pipeline</h2><p>Drag a card to update the stage and automatically record the movement.</p></div><button class="primary-btn" data-action="lead-add">＋ Add lead</button></div><div class="kanban-board">${STAGES.map(([stage,label])=>{const items=state.leads.filter(l=>l.stage===stage);return`<section class="kanban-column" data-drop-stage="${stage}"><header><div><span class="stage-dot stage-${stage}"></span><strong>${esc(label)}</strong></div><span>${items.length}</span></header><div class="kanban-cards">${items.map(l=>`<article class="kanban-card ${staleResult(l).stale?'stale':''}" draggable="true" data-drag-lead="${l.id}"><a class="pipeline-card-link" href="#/leads/${l.id}"><div class="inline-row"><strong>${esc(l.company_name)}</strong>${badgeScore(l.score||calculateScore(l).total)}</div><p>${esc(l.remarks||'No current note')}</p><div class="kanban-meta">${badgePriority(l.priority)}<span>${fmtCurrency(l.expected_monthly_value||l.estimated_budget)}</span></div><small>Follow-up: ${fmtDate(l.next_follow_up_at,true)}</small>${staleResult(l).stale?`<div class="stale-note">${esc(staleResult(l).reason)}</div>`:''}</a></article>`).join('')||'<div class="kanban-empty">Drop a lead here</div>'}</div></section>`}).join('')}</div>`}
function bindPipelineDnD(){document.querySelectorAll('[data-drag-lead]').forEach(el=>el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.dragLead)));document.querySelectorAll('[data-drop-stage]').forEach(col=>{col.addEventListener('dragover',e=>e.preventDefault());col.addEventListener('drop',async e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain'),lead=state.leads.find(l=>l.id===id),stage=col.dataset.dropStage;if(!lead||lead.stage===stage)return;try{const updated=await updateRecord('leads',id,{stage,updated_at:todayIso(),last_activity_at:todayIso()});state.leads=state.leads.map(l=>l.id===id?updated:l);await addActivity({lead_id:id,type:'stage_change',summary:`Stage changed from ${stageLabel(lead.stage)} to ${stageLabel(stage)}`});renderApp();toast('Pipeline stage updated.')}catch(err){toast(err.message,'error')}})})}

function followUpsHtml(){
  const filter=state.filters.tasks||'today',now=new Date(),week=new Date(Date.now()+7*86400000);const items=state.tasks.filter(t=>{const d=t.due_at?new Date(t.due_at):null;if(filter==='completed')return t.status==='completed';if(t.status!=='pending')return false;if(filter==='today')return d&&d.toDateString()===now.toDateString();if(filter==='overdue')return d&&d<now;if(filter==='week')return d&&d>=now&&d<=week;return true})
  return `<div class="page-actions"><div><h2>Follow-ups and tasks</h2><p>Nothing should depend on someone remembering it later.</p></div><button class="primary-btn" data-action="task-add">＋ New task</button></div><div class="segmented">${['today','overdue','week','all','completed'].map(v=>`<button class="${filter===v?'active':''}" data-action="task-filter" data-value="${v}">${v==='week'?'This week':v}</button>`).join('')}</div><section class="task-list">${items.map(t=>{const entity=state.leads.find(l=>l.id===t.lead_id)||state.clients.find(c=>c.id===t.client_id);const href=t.lead_id?`#/leads/${t.lead_id}`:t.client_id?`#/clients/${t.client_id}`:'#/follow-ups';return`<article class="task-row"><button class="task-check ${t.status==='completed'?'done':''}" data-action="task-toggle" data-id="${t.id}">${t.status==='completed'?'✓':''}</button><div class="grow"><div class="inline-row"><strong>${esc(t.title)}</strong>${badgePriority(t.priority)}${badgeStatus(t.status)}</div><p>${esc(t.description||'No additional notes')}</p><small>◷ ${fmtDate(t.due_at,true)}</small></div>${entity?`<a class="entity-link" href="${href}">${esc(entity.company_name)}</a>`:''}</article>`}).join('')||'<div class="positive-empty"><div><strong>Nothing here</strong><p>No tasks match this view.</p></div></div>'}</section>`
}
function clientsHtml(){
  const q=state.filters.clientQ||'',items=state.clients.filter(c=>[c.company_name,c.contact_person,c.industry,c.package_name].join(' ').toLowerCase().includes(q.toLowerCase()))
  return `<div class="page-actions"><div><h2>Signed clients</h2><p>Each client gets one complete workspace for scope, work, deadlines and payments.</p></div><button class="primary-btn" data-action="client-add">＋ Add client</button></div><section class="filter-bar"><label class="search-box">⌕<input data-filter="client-q" placeholder="Search client or package" value="${attr(q)}"></label></section><div class="client-grid">${items.map(c=>{const ds=state.deliverables.filter(d=>d.client_id===c.id),total=ds.reduce((s,d)=>s+Number(d.quantity),0),done=ds.reduce((s,d)=>s+Number(d.completed_quantity),0),pct=total?Math.round(done/total*100):0,due=state.payments.filter(p=>p.client_id===c.id&&['due','overdue'].includes(p.status)).reduce((s,p)=>s+Number(p.amount),0);return`<a class="client-card" href="#/clients/${c.id}"><div class="client-card-top"><div class="client-logo-placeholder">▣</div>${badgeStatus(c.status)}</div><h3>${esc(c.company_name)}</h3><p>${esc(c.package_name||'Custom client package')}</p><div class="client-money"><strong>${fmtCurrency(c.monthly_fee)}</strong><span>${esc(c.billing_cycle)}</span></div><div class="progress-line"><div style="width:${pct}%"></div></div><div class="client-card-metrics"><span><strong>${done}/${total}</strong> deliverables</span><span><strong>${due?fmtCurrency(due):'Clear'}</strong> due</span></div><div class="client-card-footer"><span>◷ Renewal: ${fmtDate(c.renewal_date)}</span></div></a>`}).join('')||'<div class="empty-state"><h3>No signed clients yet</h3><p>Convert a won lead or add a client directly.</p></div>'}</div>`
}
function clientDetailHtml(id){
  const c=state.clients.find(x=>x.id===id);if(!c)return '<div class="empty-state"><h3>Client not found</h3><a href="#/clients">Back to clients</a></div>'
  const ds=state.deliverables.filter(d=>d.client_id===id),ps=state.payments.filter(p=>p.client_id===id),acts=state.activities.filter(a=>a.client_id===id||a.lead_id===c.lead_id);const total=ds.reduce((s,d)=>s+Number(d.quantity),0),done=ds.reduce((s,d)=>s+Number(d.completed_quantity),0),pct=total?Math.round(done/total*100):0,overdue=ds.filter(d=>d.due_date&&new Date(d.due_date)<new Date()&&Number(d.completed_quantity)<Number(d.quantity)).length,received=ps.filter(p=>p.status==='paid').reduce((s,p)=>s+Number(p.amount),0),due=ps.filter(p=>['due','overdue'].includes(p.status)).reduce((s,p)=>s+Number(p.amount),0)
  return `<div class="detail-back"><a href="#/clients">← All clients</a></div><section class="profile-hero"><div><div class="inline-row"><p class="eyebrow">CLIENT WORKSPACE</p>${badgeStatus(c.status)}</div><h2>${esc(c.company_name)}</h2><p>${esc(c.scope_summary||'Add the full agreed scope so the team always knows what must be delivered.')}</p><div class="hero-links">${c.drive_folder_url?`<a target="_blank" href="${attr(c.drive_folder_url)}">↗ Drive folder</a>`:''}${c.contract_url?`<a target="_blank" href="${attr(c.contract_url)}">↗ Contract</a>`:''}</div></div><div class="hero-actions"><button class="secondary-btn" data-action="client-edit" data-id="${id}">Edit profile</button><button class="primary-btn" data-action="deliverable-add" data-client="${id}">＋ Add work</button></div></section><section class="client-summary-grid">${statMini('Monthly payment',fmtCurrency(c.monthly_fee),c.package_name||'Custom package')}${statMini('Work completed',`${pct}%`,`${done} of ${total} items`)}${statMini('Work overdue',overdue,'Past due and incomplete',overdue?'danger-text':'')}${statMini('Payment due',fmtCurrency(due),`Received total: ${fmtCurrency(received)}`)}${statMini('Next renewal',fmtDate(c.renewal_date),c.billing_cycle)}</section><section class="detail-grid"><article class="panel"><div class="panel-header"><div><p class="eyebrow">AGREED SCOPE</p><h3>What Vireon must deliver</h3></div></div><p class="long-text">${esc(c.scope_summary||'No scope summary recorded.')}</p><div class="client-service-list">${(c.services||[]).map(s=>`<span>${esc(s)}</span>`).join('')}</div></article><article class="panel"><div class="panel-header"><div><p class="eyebrow">CONTACT & CONTRACT</p><h3>Client details</h3></div></div>${detailList([['Contact person',c.contact_person],['Phone',c.phone],['Email',c.email],['Approval contact',c.approval_contact],['Contract period',`${fmtDate(c.contract_start)} — ${fmtDate(c.contract_end)}`]])}</article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">WORK TRACKER</p><h3>Done, left and due dates</h3></div><button class="primary-btn compact" data-action="deliverable-add" data-client="${id}">＋ Add deliverable</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Deliverable</th><th>Period</th><th>Progress</th><th>Status</th><th>Due</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td><strong>${esc(d.title)}</strong><small>${esc(d.category)}</small></td><td>${esc(d.period_label||'—')}</td><td><div class="quantity-control"><button data-action="deliverable-count" data-id="${d.id}" data-delta="-1">−</button><strong>${Number(d.completed_quantity)}/${Number(d.quantity)}</strong><button data-action="deliverable-count" data-id="${d.id}" data-delta="1">+</button></div></td><td><select data-action="deliverable-status" data-id="${d.id}" class="inline-select"><option value="not_started" ${d.status==='not_started'?'selected':''}>Not started</option><option value="in_progress" ${d.status==='in_progress'?'selected':''}>In progress</option><option value="review" ${d.status==='review'?'selected':''}>Review</option><option value="approved" ${d.status==='approved'?'selected':''}>Approved</option><option value="delivered" ${d.status==='delivered'?'selected':''}>Delivered</option><option value="blocked" ${d.status==='blocked'?'selected':''}>Blocked</option></select></td><td class="${d.due_date&&new Date(d.due_date)<new Date()&&Number(d.completed_quantity)<Number(d.quantity)?'danger-text':''}">${fmtDate(d.due_date)}</td><td><button class="text-danger" data-action="deliverable-delete" data-id="${d.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>${ds.length?'':'<div class="empty-state"><h3>No work added</h3><p>Add every agreed video, graphic, shoot or task.</p></div>'}</article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">PAYMENTS</p><h3>Billing and collection history</h3></div><button class="primary-btn compact" data-action="payment-add" data-client="${id}">＋ Add payment</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Description</th><th>Amount</th><th>Due</th><th>Status</th><th>Paid on</th><th>Action</th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.description)}</strong><small>${esc(p.payment_method||'No method')}</small></td><td>${fmtCurrency(p.amount)}</td><td>${fmtDate(p.due_date)}</td><td><select data-action="payment-status" data-id="${p.id}" class="inline-select">${['upcoming','due','overdue','paid','waived'].map(v=>`<option value="${v}" ${p.status===v?'selected':''}>${v}</option>`).join('')}</select></td><td>${fmtDate(p.paid_at)}</td><td>${p.status!=='paid'?`<button class="secondary-btn compact" data-action="payment-paid" data-id="${p.id}">✓ Mark paid</button>`:''}</td></tr>`).join('')}</tbody></table></div></article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">FULL HISTORY</p><h3>Client timeline</h3></div></div>${timelineHtml(acts)}</article></section>`
}
function statMini(label,value,note,cls=''){return `<article><span>${esc(label)}</span><strong class="${cls}">${value}</strong><small>${esc(note||'')}</small></article>`}
function activitiesHtml(){return `<div class="page-actions"><div><h2>Activity history</h2><p>A chronological record of calls, messages, meetings, proposals and internal notes.</p></div></div><section class="panel">${timelineHtml(state.activities)}</section>`}
function quickRepliesHtml(){const q=state.filters.replyQ||'',items=state.quickReplies.filter(x=>!x.is_archived&&[x.title,x.category,x.message_body].join(' ').toLowerCase().includes(q.toLowerCase()));return `<div class="page-actions"><div><h2>Quick Replies</h2><p>Save messages once, personalize placeholders and copy them instantly.</p></div><button class="primary-btn" data-action="reply-add">＋ Add reply</button></div><section class="filter-bar"><label class="search-box">⌕<input data-filter="reply-q" placeholder="Search messages or categories" value="${attr(q)}"></label></section><div class="reply-grid">${items.map(x=>`<article class="reply-card"><header><div><span class="reply-category">${esc(x.category)}</span><h3>${esc(x.title)}</h3></div><button class="icon-btn favorite" data-action="reply-favorite" data-id="${x.id}">${x.is_favorite?'♥':'♡'}</button></header><p>${esc(x.message_body)}</p><div class="placeholder-list">${Array.from(String(x.message_body).matchAll(/{{(.*?)}}/g)).map(m=>`<span>${esc(m[0])}</span>`).join('')}</div><footer><small>Used ${Number(x.usage_count||0)} times</small><div><button class="ghost-btn compact" data-action="reply-edit" data-id="${x.id}">Edit</button><button class="ghost-btn compact" data-action="reply-archive" data-id="${x.id}">Archive</button><button class="primary-btn compact" data-action="reply-copy" data-id="${x.id}">□ Copy</button></div></footer></article>`).join('')}</div>`}
function reportsHtml(){const group=(key)=>Object.entries(state.leads.reduce((a,l)=>{const k=l[key]||'Unknown';a[k]=(a[k]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1]),bar=(data,valueFmt=v=>v)=>{const max=Math.max(1,...data.map(x=>Number(x[1])));return`<div class="report-bars">${data.map(([label,value])=>`<div><div><span>${esc(label)}</span><strong>${valueFmt(value)}</strong></div><div class="report-track"><i style="width:${Math.max(2,Number(value)/max*100)}%"></i></div></div>`).join('')}</div>`};const pipeline=STAGES.map(([id,label])=>[label,state.leads.filter(l=>l.stage===id).reduce((s,l)=>s+Number(l.expected_monthly_value||l.estimated_budget||0),0)]);const completed=state.tasks.filter(t=>t.status==='completed').length,total=state.deliverables.reduce((s,d)=>s+Number(d.quantity),0),done=state.deliverables.reduce((s,d)=>s+Number(d.completed_quantity),0);return `<div class="page-actions"><div><h2>Reports</h2><p>Simple operational signals for sales, follow-up and client delivery.</p></div></div><section class="report-kpis">${statMini('Active clients',state.clients.filter(c=>c.status==='active').length,'')}${statMini('Follow-up completion',`${state.tasks.length?Math.round(completed/state.tasks.length*100):0}%`,'')}${statMini('Delivery completion',`${total?Math.round(done/total*100):0}%`,'')}${statMini('Monthly recurring revenue',fmtCurrency(state.clients.filter(c=>c.status==='active').reduce((s,c)=>s+Number(c.monthly_fee),0)),'')}</section><section class="report-grid"><article class="panel"><div class="panel-header"><div><p class="eyebrow">ACQUISITION</p><h3>Leads by source</h3></div></div>${bar(group('lead_source'))}</article><article class="panel"><div class="panel-header"><div><p class="eyebrow">MARKETS</p><h3>Leads by industry</h3></div></div>${bar(group('industry'))}</article><article class="panel full-span"><div class="panel-header"><div><p class="eyebrow">VALUE</p><h3>Pipeline value by stage</h3></div></div>${bar(pipeline,fmtCurrency)}</article></section>`}

function settingsHtml(){return `<div class="page-actions"><div><h2>Settings</h2><p>Configure the cloud system, team security and Google Sheets backup.</p></div></div><section class="settings-grid"><article class="panel"><div class="settings-icon">▤</div><div><p class="eyebrow">DATABASE</p><h3>Supabase cloud</h3><p>${state.cloud?'Connected. Your data can be securely shared across devices.':'Not configured. The app is using browser-only local storage.'}</p><div class="connection-status ${state.cloud?'connected':'pending'}">${state.cloud?'✓ Cloud mode enabled':'◷ Environment variables required'}</div></div></article><article class="panel"><div class="settings-icon">✓</div><div><p class="eyebrow">TEAM ACCESS</p><h3>Authentication and roles</h3><p>Create each teammate through Supabase Authentication. Their profile can be Admin or Team Member.</p><small>There is no public signup page, so only approved users can access the CRM.</small></div></article></section><section class="panel sheets-panel"><div class="panel-header"><div><p class="eyebrow">TWO-WAY BACKUP</p><h3>Google Sheets integration</h3><p>Supabase stays the main database. Your Sheet becomes an import source and synchronized backup.</p></div><div class="settings-icon">▦</div></div><div class="setup-steps"><div><span>1</span><p>Open your existing Sheet and choose <strong>Extensions → Apps Script</strong>.</p></div><div><span>2</span><p>Paste the included <code>google-apps-script/Code.gs</code> and set the shared secret.</p></div><div><span>3</span><p>Deploy as a Web App, execute as you, and allow Anyone. Copy its deployment URL.</p></div><div><span>4</span><p>Add the URL and secret to Netlify environment variables, then redeploy.</p></div></div><div class="sheet-actions"><button class="secondary-btn" data-action="sheets-test" ${state.cloud?'':'disabled'}>↻ Test connection</button><button class="secondary-btn" data-action="sheets-pull" ${state.cloud?'':'disabled'}>⇩ Import new rows</button><button class="primary-btn" data-action="sheets-push" ${state.cloud?'':'disabled'}>▦ Update Sheet backup</button></div><div id="sync-result"></div><div class="environment-list"><h4>Required Netlify environment variables</h4><code>SUPABASE_URL</code><code>SUPABASE_PUBLISHABLE_KEY</code><code>GOOGLE_SHEETS_WEB_APP_URL</code><code>GOOGLE_SHEETS_SHARED_SECRET</code></div></section><section class="panel"><div class="panel-header"><div><p class="eyebrow">IMPORTANT</p><h3>Recommended sync rule</h3></div></div><p class="long-text">After the first import, edit leads inside Vireon CRM—not directly in both places. Use “Update Sheet backup” whenever you want the newest CRM data copied to your Sheet. This prevents two different versions from being edited at the same time.</p></section>`}

function openModal(title,body,wide=false){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="modal-close"><section class="modal-card ${wide?'modal-wide':''}" onclick="event.stopPropagation()"><header class="modal-header"><div><p class="eyebrow">VIREON CRM</p><h2>${esc(title)}</h2></div><button class="icon-btn" data-action="modal-close">×</button></header><div class="modal-body">${body}</div></section></div>`}
function closeModal(){modalRoot.innerHTML=''}
function selectOptions(items,value){return items.map(v=>{const item=Array.isArray(v)?v:[v,v];return`<option value="${attr(item[0])}" ${String(value||'')===String(item[0])?'selected':''}>${esc(item[1])}</option>`}).join('')}
function checked(v){return v?'checked':''}
function leadFormHtml(lead={}){
  const req=state.requirements.find(r=>r.lead_id===lead.id)||{}
  return `<form id="lead-form" class="form-stack" data-id="${attr(lead.id||'')}"><div id="lead-form-alert"></div><section class="form-section"><div class="section-heading"><div><p class="eyebrow">FAST ENTRY</p><h3>Contact and pipeline</h3></div></div><div class="form-grid three"><label><span>Company / lead name *</span><input name="company_name" value="${attr(lead.company_name||'')}" required autofocus></label><label><span>Contact person</span><input name="contact_person" value="${attr(lead.contact_person||'')}"></label><label><span>Business type</span><select name="industry"><option value="">Select</option>${selectOptions(INDUSTRIES,lead.industry)}</select></label><label><span>Phone</span><input name="phone" value="${attr(lead.phone||'')}"></label><label><span>WhatsApp</span><input name="whatsapp" value="${attr(lead.whatsapp||'')}"></label><label><span>Email</span><input name="email" type="email" value="${attr(lead.email||'')}"></label><label><span>Lead source</span><select name="lead_source"><option value="">Select</option>${selectOptions(SOURCES,lead.lead_source)}</select></label><label><span>Pipeline stage</span><select name="stage">${selectOptions(STAGES,lead.stage||'new')}</select></label><label><span>Priority</span><select name="priority">${selectOptions(PRIORITIES,lead.priority||'medium')}</select></label><label><span>Estimated budget (NPR)</span><input name="estimated_budget" type="number" value="${attr(lead.estimated_budget??'')}"></label><label><span>Expected monthly value</span><input name="expected_monthly_value" type="number" value="${attr(lead.expected_monthly_value??'')}"></label><label><span>Next follow-up</span><input name="next_follow_up_at" type="datetime-local" value="${attr(inputDateTime(lead.next_follow_up_at))}"></label></div></section><section class="form-section smart-note-box"><div class="section-heading"><div><p class="eyebrow">FREE SMART PARSER</p><h3>Paste rough notes</h3></div><button type="button" class="secondary-btn" data-action="smart-parse">✦ Smart Parse</button></div><textarea name="rough_note" rows="3" placeholder="talked on phone, needs 12-15 videos monthly, budget around 20000, send proposal then schedule meeting"></textarea></section><section class="form-section"><div class="section-heading"><div><p class="eyebrow">CLIENT NEEDS</p><h3>Requirements</h3></div></div><div class="form-grid three"><label><span>Videos monthly</span><input name="monthly_videos" type="number" value="${attr(req.monthly_videos??'')}"></label><label><span>Graphics monthly</span><input name="monthly_graphics" type="number" value="${attr(req.monthly_graphics??'')}"></label><label><span>Shoot frequency</span><input name="shoot_frequency" value="${attr(req.shoot_frequency||'')}"></label><label><span>Posting requirements</span><input name="posting_requirements" value="${attr(req.posting_requirements||'')}"></label><label><span>Approximate budget</span><input name="approximate_budget" type="number" value="${attr(req.approximate_budget??'')}"></label><label><span>Competitor / references</span><input name="competitor_references" value="${attr(req.competitor_references||'')}"></label></div><div class="check-grid"><label class="check-card"><input name="models_required" type="checkbox" ${checked(req.models_required)}><span>Models</span></label><label class="check-card"><input name="voiceover_required" type="checkbox" ${checked(req.voiceover_required)}><span>Voice-over</span></label><label class="check-card"><input name="video_editing_required" type="checkbox" ${checked(req.video_editing_required)}><span>Video editing</span></label><label class="check-card"><input name="content_creator_required" type="checkbox" ${checked(req.content_creator_required)}><span>Content creator</span></label><label class="check-card"><input name="social_media_handling_required" type="checkbox" ${checked(req.social_media_handling_required)}><span>Social media handling</span></label></div><label><span>Current situation / remarks</span><textarea name="remarks" rows="3">${esc(lead.remarks||'')}</textarea></label><label><span>Special expectations</span><textarea name="special_expectations" rows="2">${esc(req.special_expectations||'')}</textarea></label></section><details class="advanced-details"><summary>Scoring and links</summary><div class="form-grid three"><label><span>Engagement (0–5)</span><input name="engagement_level" type="number" min="0" max="5" value="${attr(lead.engagement_level??2)}"></label><label><span>Meeting interest (0–5)</span><input name="meeting_interest" type="number" min="0" max="5" value="${attr(lead.meeting_interest??0)}"></label><label><span>Urgency (0–5)</span><input name="urgency_level" type="number" min="0" max="5" value="${attr(lead.urgency_level??2)}"></label><label><span>Requirements complete (%)</span><input name="requirements_completeness" type="number" min="0" max="100" value="${attr(lead.requirements_completeness??0)}"></label><label class="check-card inline-check"><input name="decision_maker_contacted" type="checkbox" ${checked(lead.decision_maker_contacted)}><span>Decision-maker contacted</span></label><label><span>Closing probability (%)</span><input name="closing_probability" type="number" min="0" max="100" value="${attr(lead.closing_probability??'')}"></label><label><span>Date first contacted</span><input name="date_first_contacted" type="datetime-local" value="${attr(inputDateTime(lead.date_first_contacted))}"></label><label><span>Address</span><input name="address" value="${attr(lead.address||'')}"></label><label><span>Website</span><input name="website" value="${attr(lead.website||'')}"></label><label><span>Instagram</span><input name="instagram" value="${attr(lead.instagram||'')}"></label><label><span>Facebook</span><input name="facebook" value="${attr(lead.facebook||'')}"></label><label><span>TikTok</span><input name="tiktok" value="${attr(lead.tiktok||'')}"></label><label><span>Proposal link</span><input name="proposal_url" value="${attr(lead.proposal_url||'')}"></label><label><span>Google Drive folder</span><input name="drive_folder_url" value="${attr(lead.drive_folder_url||'')}"></label></div></details><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">${lead.id?'Save changes':'Add lead'}</button></div></form>`
}
function clientFormHtml(client={},lead=null){return `<form id="client-form" class="form-stack" data-id="${attr(client.id||'')}" data-lead="${attr(lead?.id||'')}"><div class="form-grid three"><label><span>Company name *</span><input name="company_name" value="${attr(client.company_name||lead?.company_name||'')}" required></label><label><span>Contact person</span><input name="contact_person" value="${attr(client.contact_person||lead?.contact_person||'')}"></label><label><span>Industry</span><input name="industry" value="${attr(client.industry||lead?.industry||'')}"></label><label><span>Monthly payment (NPR) *</span><input name="monthly_fee" type="number" value="${attr(client.monthly_fee??lead?.expected_monthly_value??lead?.estimated_budget??0)}" required></label><label><span>Package name</span><input name="package_name" value="${attr(client.package_name||'')}"></label><label><span>Billing cycle</span><select name="billing_cycle">${selectOptions([['monthly','Monthly'],['quarterly','Quarterly'],['one_time','One-time']],client.billing_cycle||'monthly')}</select></label><label><span>Contract start</span><input name="contract_start" type="date" value="${attr(String(client.contract_start||'').slice(0,10))}"></label><label><span>Contract end</span><input name="contract_end" type="date" value="${attr(String(client.contract_end||'').slice(0,10))}"></label><label><span>Next renewal / payment</span><input name="renewal_date" type="date" value="${attr(String(client.renewal_date||'').slice(0,10))}"></label><label><span>Phone</span><input name="phone" value="${attr(client.phone||lead?.phone||'')}"></label><label><span>Email</span><input name="email" value="${attr(client.email||lead?.email||'')}"></label><label><span>Approval contact</span><input name="approval_contact" value="${attr(client.approval_contact||'')}"></label></div><label><span>Services included — comma separated</span><input name="services" value="${attr((client.services||[]).join(', '))}" placeholder="Video production, graphics, posting, models"></label><label><span>Scope summary / what Vireon must deliver</span><textarea name="scope_summary" rows="4">${esc(client.scope_summary||'')}</textarea></label><div class="form-grid two"><label><span>Google Drive folder</span><input name="drive_folder_url" value="${attr(client.drive_folder_url||'')}"></label><label><span>Contract link</span><input name="contract_url" value="${attr(client.contract_url||'')}"></label></div><label><span>Internal notes</span><textarea name="notes" rows="2">${esc(client.notes||'')}</textarea></label><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">${lead?'Create client workspace':'Save client'}</button></div></form>`}
function formObject(form){const fd=new FormData(form),o={};for(const [k,v] of fd.entries())o[k]=v;form.querySelectorAll('input[type=checkbox]').forEach(x=>o[x.name]=x.checked);return o}

function activityFormHtml(leadId,clientId){return `<form id="activity-form" class="form-stack" data-lead="${attr(leadId||'')}" data-client="${attr(clientId||'')}"><label><span>Activity type</span><select name="type"><option value="call">Call</option><option value="whatsapp">WhatsApp</option><option value="email">Email</option><option value="physical_meeting">Physical meeting</option><option value="online_meeting">Online meeting</option><option value="proposal">Proposal sent</option><option value="follow_up">Follow-up</option><option value="payment">Payment</option><option value="internal_note">Internal note</option></select></label><label><span>Short summary</span><input name="summary" required autofocus></label><label><span>Details / client response</span><textarea name="details" rows="4"></textarea></label><label><span>Next action</span><input name="next_action" placeholder="Send revised proposal"></label><label><span>Next follow-up</span><input name="next_follow_up_at" type="datetime-local"></label><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">Save activity</button></div></form>`}
function taskFormHtml(){return `<form id="task-form" class="form-stack"><label><span>Task title</span><input name="title" required autofocus></label><label><span>Related lead</span><select name="lead_id"><option value="">None</option>${state.leads.map(l=>`<option value="${l.id}">${esc(l.company_name)}</option>`).join('')}</select></label><label><span>Related client</span><select name="client_id"><option value="">None</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.company_name)}</option>`).join('')}</select></label><label><span>Due date and time</span><input name="due_at" type="datetime-local"></label><label><span>Priority</span><select name="priority">${selectOptions(PRIORITIES,'high')}</select></label><label><span>Description</span><textarea name="description" rows="3"></textarea></label><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">Create task</button></div></form>`}
function deliverableFormHtml(clientId){return `<form id="deliverable-form" class="form-stack" data-client="${attr(clientId)}"><label><span>Deliverable name</span><input name="title" placeholder="Trainer-led educational videos" required autofocus></label><div class="form-grid two"><label><span>Category</span><select name="category"><option>Video</option><option>Graphic</option><option>Shoot</option><option>Posting</option><option>Strategy</option><option>Other</option></select></label><label><span>Quantity</span><input name="quantity" type="number" min="1" value="1"></label><label><span>Period</span><input name="period_label" value="Current month"></label><label><span>Due date</span><input name="due_date" type="date"></label></div><label><span>Notes</span><textarea name="notes" rows="2"></textarea></label><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">Add work</button></div></form>`}
function paymentFormHtml(clientId){const c=state.clients.find(x=>x.id===clientId);return `<form id="payment-form" class="form-stack" data-client="${attr(clientId)}"><label><span>Description</span><input name="description" value="Monthly package"></label><label><span>Amount (NPR)</span><input name="amount" type="number" value="${attr(c?.monthly_fee||0)}"></label><label><span>Due date</span><input name="due_date" type="date"></label><label><span>Status</span><select name="status">${selectOptions(['upcoming','due','overdue','paid'],'upcoming')}</select></label><div class="form-actions"><button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">Add payment</button></div></form>`}
function replyFormHtml(item={}){return `<form id="reply-form" class="form-stack" data-id="${attr(item.id||'')}"><label><span>Title</span><input name="title" value="${attr(item.title||'')}" required></label><div class="form-grid two"><label><span>Category</span><select name="category">${selectOptions(['Requirements Request','Proposal Sent','Follow-up','Meeting Scheduling','Thank You','Payment Reminder','Onboarding','General'],item.category||'Follow-up')}</select></label><label><span>Language</span><select name="language">${selectOptions(['English','Nepali','Roman Nepali'],item.language||'English')}</select></label></div><label><span>Message</span><textarea name="message_body" rows="7" required>${esc(item.message_body||'')}</textarea></label><p class="helper-text">Supported placeholders: {{company_name}}, {{contact_name}}, {{proposal_link}}, {{meeting_time}}.</p><label class="check-card"><input name="is_favorite" type="checkbox" ${checked(item.is_favorite)}><span>Favorite</span></label><div class="form-actions">${item.id?`<button type="button" class="ghost-btn danger-zone" data-action="reply-delete" data-id="${item.id}">Delete</button>`:''}<button type="button" class="ghost-btn" data-action="modal-close">Cancel</button><button class="primary-btn">Save reply</button></div></form>`}

async function sheetsCall(action,rows){const response=await fetch('/api/google-sheets-sync',{method:'POST',headers:{'Content-Type':'application/json',...(state.session?.access_token?{Authorization:`Bearer ${state.session.access_token}`}:{})},body:JSON.stringify({action,rows})});const payload=await response.json();if(!response.ok||payload.ok===false)throw new Error(payload.error||payload.message||'Sheets request failed');return payload}
const sheetAliases={'lead name':'company_name','company name':'company_name','contact number':'phone','phone':'phone','email':'email','business type':'industry','industry':'industry','lead source':'lead_source','date first contacted':'date_first_contacted','current situation / remarks':'remarks','remarks':'remarks','lead status':'stage','status':'stage','priority':'priority','next follow-up date':'next_follow_up_at','expected monthly value':'expected_monthly_value','budget':'estimated_budget'}
const sheetStageMap={'new lead':'new','new':'new','to call':'new','contacted':'contacted','requirements collected':'requirements','proposal preparing':'proposal_preparing','proposal sent':'proposal_sent','waiting response':'follow_up','waiting response...':'follow_up','follow up':'follow_up','follow-up':'follow_up','meeting scheduled':'meeting','negotiating':'negotiating','won':'won','lost':'lost','no deal':'lost','on hold':'on_hold','not priority':'on_hold'}
function mapSheetRow(row){const lead={stage:'new',priority:'medium'};for(const [header,value]of Object.entries(row)){const key=sheetAliases[header.trim().toLowerCase()];if(!key||value===null||value==='')continue;if(key==='stage')lead.stage=sheetStageMap[String(value).trim().toLowerCase()]||'new';else if(key==='priority'){const p=String(value).toLowerCase();lead.priority=p.includes('urgent')?'urgent':p.includes('high')?'high':p.includes('low')?'low':'medium'}else if(['estimated_budget','expected_monthly_value'].includes(key))lead[key]=Number(String(value).replace(/[^0-9.]/g,''))||0;else if(['date_first_contacted','next_follow_up_at'].includes(key)){const d=new Date(value);if(!Number.isNaN(d.getTime()))lead[key]=d.toISOString()}else lead[key]=value}return lead}
function leadsForSheet(){return state.leads.map(l=>({'Lead Name':l.company_name,'Contact Number':l.phone||'','Email':l.email||'','Business Type':l.industry||'','Lead Source':l.lead_source||'','Date First Contacted':String(l.date_first_contacted||'').slice(0,10),'Current Situation / Remarks':l.remarks||'','Lead Status':l.stage,'Priority':l.priority,'Next Follow-up Date':String(l.next_follow_up_at||'').slice(0,10),'Expected Monthly Value':l.expected_monthly_value||'','Score':l.score||''}))}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action
  try{
    if(action==='modal-close'){closeModal();return}
    if(action==='mobile-open'){document.getElementById('sidebar')?.classList.add('mobile-open');return}
    if(action==='mobile-close'){document.getElementById('sidebar')?.classList.remove('mobile-open');return}
    if(action==='logout'){await logout();return}
    if(action==='local-enter'){location.hash='#/dashboard';renderApp();return}
    if(action==='lead-add'){openModal('Add a new lead',leadFormHtml(),true);return}
    if(action==='lead-edit'){const lead=state.leads.find(l=>l.id===el.dataset.id);openModal('Edit lead',leadFormHtml(lead),true);return}
    if(action==='smart-parse'){const form=document.getElementById('lead-form'),p=smartParse(form.elements.rough_note.value);if(p.cleaned)form.elements.remarks.value=p.cleaned;if(p.budget){form.elements.estimated_budget.value=p.budget;form.elements.approximate_budget.value=p.budget}if(p.videos)form.elements.monthly_videos.value=p.videos;if(p.graphics)form.elements.monthly_graphics.value=p.graphics;if(p.stage)form.elements.stage.value=p.stage;toast('Notes parsed. Review the suggested fields before saving.');return}
    if(action==='activity-add'){openModal('Record client interaction',activityFormHtml(el.dataset.lead,el.dataset.client));return}
    if(action==='client-convert'){const lead=state.leads.find(l=>l.id===el.dataset.lead);openModal('Convert lead to signed client',clientFormHtml({},lead),true);return}
    if(action==='client-add'){openModal('Add signed client',clientFormHtml(),true);return}
    if(action==='client-edit'){const client=state.clients.find(c=>c.id===el.dataset.id);openModal('Edit client profile',clientFormHtml(client),true);return}
    if(action==='task-add'){openModal('Create follow-up task',taskFormHtml());return}
    if(action==='task-filter'){state.filters.tasks=el.dataset.value;renderApp();return}
    if(action==='task-toggle'){const task=state.tasks.find(t=>t.id===el.dataset.id),status=task.status==='completed'?'pending':'completed';const updated=await updateRecord('tasks',task.id,{status,completed_at:status==='completed'?todayIso():null});state.tasks=state.tasks.map(t=>t.id===task.id?updated:t);renderApp();return}
    if(action==='toggle-stale'){state.filters.leads={...(state.filters.leads||{}),stale:!(state.filters.leads||{}).stale};renderApp();return}
    if(action==='deliverable-add'){openModal('Add client deliverable',deliverableFormHtml(el.dataset.client));return}
    if(action==='deliverable-count'){const d=state.deliverables.find(x=>x.id===el.dataset.id),next=Math.max(0,Math.min(Number(d.quantity),Number(d.completed_quantity)+Number(el.dataset.delta))),status=next>=Number(d.quantity)?'delivered':d.status==='delivered'?'in_progress':d.status;const updated=await updateRecord('deliverables',d.id,{completed_quantity:next,status});state.deliverables=state.deliverables.map(x=>x.id===d.id?updated:x);renderApp();return}
    if(action==='deliverable-delete'){if(!confirm('Remove this deliverable?'))return;await deleteRecord('deliverables',el.dataset.id);state.deliverables=state.deliverables.filter(x=>x.id!==el.dataset.id);renderApp();return}
    if(action==='payment-add'){openModal('Add payment record',paymentFormHtml(el.dataset.client));return}
    if(action==='payment-paid'){const p=state.payments.find(x=>x.id===el.dataset.id),updated=await updateRecord('payments',p.id,{status:'paid',paid_at:todayIso()});state.payments=state.payments.map(x=>x.id===p.id?updated:x);renderApp();return}
    if(action==='reply-add'){openModal('Add quick reply',replyFormHtml());return}
    if(action==='reply-edit'){openModal('Edit quick reply',replyFormHtml(state.quickReplies.find(x=>x.id===el.dataset.id)));return}
    if(action==='reply-favorite'){const q=state.quickReplies.find(x=>x.id===el.dataset.id),updated=await updateRecord('quickReplies',q.id,{is_favorite:!q.is_favorite});state.quickReplies=state.quickReplies.map(x=>x.id===q.id?updated:x);renderApp();return}
    if(action==='reply-archive'){const q=state.quickReplies.find(x=>x.id===el.dataset.id),updated=await updateRecord('quickReplies',q.id,{is_archived:true});state.quickReplies=state.quickReplies.map(x=>x.id===q.id?updated:x);renderApp();return}
    if(action==='reply-delete'){if(!confirm('Delete this quick reply?'))return;await deleteRecord('quickReplies',el.dataset.id);state.quickReplies=state.quickReplies.filter(x=>x.id!==el.dataset.id);closeModal();renderApp();return}
    if(action==='reply-copy'){const q=state.quickReplies.find(x=>x.id===el.dataset.id);await navigator.clipboard.writeText(q.message_body);const updated=await updateRecord('quickReplies',q.id,{usage_count:Number(q.usage_count||0)+1,last_used_at:todayIso()});state.quickReplies=state.quickReplies.map(x=>x.id===q.id?updated:x);toast('Reply copied.');renderApp();return}
    if(action==='sheets-test'){setSyncResult('Testing connection…');const r=await sheetsCall('test');setSyncResult(r.message||'Connected.');return}
    if(action==='sheets-push'){setSyncResult('Updating Google Sheet…');const r=await sheetsCall('push',leadsForSheet());setSyncResult(r.message||`Exported ${r.count||state.leads.length} leads.`);return}
    if(action==='sheets-pull'){setSyncResult('Reading Google Sheet…');const r=await sheetsCall('pull');let imported=0,skipped=0;for(const row of(r.rows||[])){const mapped=mapSheetRow(row);if(!mapped.company_name)continue;if(findDuplicates(mapped).some(m=>m.confidence>=45)){skipped++;continue}await saveLead(mapped,null,null);imported++}setSyncResult(`Imported ${imported} new leads. Skipped ${skipped} possible duplicates.`);renderApp();return}
  }catch(error){toast(error.message||'Action failed.','error');setSyncResult(error.message||'Action failed.',true)}
})

document.addEventListener('change',async event=>{
  const el=event.target
  try{
    if(el.dataset.filter==='lead-q'){state.filters.leads={...(state.filters.leads||{}),q:el.value};renderApp()}
    if(el.dataset.filter==='lead-stage'){state.filters.leads={...(state.filters.leads||{}),stage:el.value};renderApp()}
    if(el.dataset.filter==='lead-industry'){state.filters.leads={...(state.filters.leads||{}),industry:el.value};renderApp()}
    if(el.dataset.filter==='lead-source'){state.filters.leads={...(state.filters.leads||{}),source:el.value};renderApp()}
    if(el.dataset.filter==='client-q'){state.filters.clientQ=el.value;renderApp()}
    if(el.dataset.filter==='reply-q'){state.filters.replyQ=el.value;renderApp()}
    if(el.dataset.action==='deliverable-status'){const d=state.deliverables.find(x=>x.id===el.dataset.id),updated=await updateRecord('deliverables',d.id,{status:el.value});state.deliverables=state.deliverables.map(x=>x.id===d.id?updated:x);renderApp()}
    if(el.dataset.action==='payment-status'){const p=state.payments.find(x=>x.id===el.dataset.id),changes={status:el.value};if(el.value==='paid'&&!p.paid_at)changes.paid_at=todayIso();const updated=await updateRecord('payments',p.id,changes);state.payments=state.payments.map(x=>x.id===p.id?updated:x);renderApp()}
  }catch(error){toast(error.message,'error')}
})

document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target
  try{
    if(form.id==='login-form'){const btn=form.querySelector('button');btn.disabled=true;btn.textContent='Signing in…';try{await login(form.email.value,form.password.value);renderApp()}catch(error){document.getElementById('login-error').textContent=error.message;btn.disabled=false;btn.textContent='Sign in'}return}
    if(form.id==='lead-form'){
      const raw=formObject(form),id=form.dataset.id||null
      const reqKeys=['monthly_videos','monthly_graphics','shoot_frequency','posting_requirements','approximate_budget','competitor_references','models_required','voiceover_required','video_editing_required','content_creator_required','social_media_handling_required','special_expectations'];const req={};reqKeys.forEach(k=>{req[k]=raw[k];delete raw[k]});delete raw.rough_note
      if(raw.next_follow_up_at)raw.next_follow_up_at=new Date(raw.next_follow_up_at).toISOString();else raw.next_follow_up_at=null
      if(raw.date_first_contacted)raw.date_first_contacted=new Date(raw.date_first_contacted).toISOString();else if(!id)raw.date_first_contacted=new Date().toISOString();else raw.date_first_contacted=null
      const matches=findDuplicates(raw,state.leads.filter(l=>l.id!==id)).filter(m=>m.confidence>=35)
      if(matches.length&&!form.dataset.confirmed){document.getElementById('lead-form-alert').innerHTML=`<div class="duplicate-panel"><div class="duplicate-title"><strong>Possible duplicate found</strong></div><div class="duplicate-list">${matches.slice(0,3).map(m=>`<div class="duplicate-row"><div><strong>${esc(m.lead.company_name)}</strong><small>${esc(m.reasons.join(' · '))}</small></div><span>${m.confidence}%</span></div>`).join('')}</div><p>Review these records. Submit again only if this really is a separate lead.</p></div>`;form.dataset.confirmed='true';form.querySelector('button[type=submit]').textContent='Save anyway';return}
      const saved=await saveLead(raw,req,id);closeModal();location.hash=`#/leads/${saved.id}`;renderApp();toast(id?'Lead updated.':'Lead added.');return
    }
    if(form.id==='activity-form'){const o=formObject(form);if(o.next_follow_up_at)o.next_follow_up_at=new Date(o.next_follow_up_at).toISOString();else o.next_follow_up_at=null;o.lead_id=form.dataset.lead||null;o.client_id=form.dataset.client||null;await addActivity(o);if(o.next_action)await createTask({lead_id:o.lead_id,client_id:o.client_id,title:o.next_action,due_at:o.next_follow_up_at,priority:'high'});closeModal();renderApp();toast('Activity recorded.');return}
    if(form.id==='task-form'){const o=formObject(form);o.lead_id=o.lead_id||null;o.client_id=o.client_id||null;o.due_at=o.due_at?new Date(o.due_at).toISOString():null;await createTask(o);closeModal();renderApp();toast('Task created.');return}
    if(form.id==='client-form'){const o=formObject(form),lead=state.leads.find(l=>l.id===form.dataset.lead);if(form.dataset.id)o.id=form.dataset.id;const client=await saveClient(o,lead);closeModal();location.hash=`#/clients/${client.id}`;renderApp();toast(lead?'Client workspace created.':'Client saved.');return}
    if(form.id==='deliverable-form'){const o=formObject(form);o.client_id=form.dataset.client;o.quantity=Number(o.quantity||1);o.completed_quantity=0;o.status='not_started';const d=await insertRecord('deliverables',o);state.deliverables=[...state.deliverables.filter(x=>x.id!==d.id),d];closeModal();renderApp();toast('Deliverable added.');return}
    if(form.id==='payment-form'){const o=formObject(form);o.client_id=form.dataset.client;o.amount=Number(o.amount||0);if(o.status==='paid')o.paid_at=todayIso();const p=await insertRecord('payments',o);state.payments=[...state.payments.filter(x=>x.id!==p.id),p];closeModal();renderApp();toast('Payment record added.');return}
    if(form.id==='reply-form'){const o=formObject(form),id=form.dataset.id;o.usage_count=id?Number(state.quickReplies.find(x=>x.id===id)?.usage_count||0):0;o.is_archived=false;let q;if(id){q=await updateRecord('quickReplies',id,o);state.quickReplies=state.quickReplies.map(x=>x.id===id?q:x)}else{q=await insertRecord('quickReplies',o);state.quickReplies=[q,...state.quickReplies]}closeModal();renderApp();toast('Quick reply saved.');return}
  }catch(error){toast(error.message||'Could not save.','error')}
})

function setSyncResult(message,error=false){const el=document.getElementById('sync-result');if(el)el.innerHTML=`<div class="sync-message ${error?'form-error':''}">${esc(message)}</div>`}
window.addEventListener('hashchange',renderApp)

;(async function init(){
  await loadConfig()
  if(state.cloud){try{state.session=JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{}}
  await loadAll()
  if(state.cloud&&!state.session)location.hash='#/login';else if(!location.hash||location.hash==='#/login')location.hash='#/dashboard'
  renderApp()
})()
